function varargout = test_acav_twin(fixturePath)
%TEST_ACAV_TWIN Check the MATLAB twin against the Python reference.
%
%   test_acav_twin()                     % uses the shipped fixtures
%   results = test_acav_twin(path)       % explicit fixture file
%
% The MATLAB twin is a transcription of acav/twin_reference.py. A sign
% error in a transcription does not crash: it steers the twin smoothly
% to a wrong attitude. The two implementations are therefore held
% together by data: this replays fixtures generated by the reference
% (config/twin_fixtures.json) and asserts agreement to 1e-9.
%
% Every check runs, nothing stops at the first failure, and the summary
% says what is wrong.
%
% Called with an output it returns the struct array; called as a
% statement it prints the summary and ERRORS if anything failed, so
% `matlab -batch test_acav_twin` exits non-zero. That mirrors
% verify_acav_scenario.py's exit-code contract.

    if nargin < 1 || isempty(fixturePath)
        here = fileparts(mfilename('fullpath'));
        fixturePath = fullfile(fileparts(here), 'acav', 'config', ...
            'twin_fixtures.json');
    end
    if ~isfile(fixturePath)
        error('test_acav_twin:NoFixtures', ...
            ['fixtures not found at %s.\nGenerate them with:\n' ...
             '  python src/acav/scripts/export_twin_fixtures.py'], ...
            fixturePath);
    end

    fx = jsondecode(fileread(fixturePath));
    EXPECTED_VERSION = 6;
    if fx.version ~= EXPECTED_VERSION
        error('test_acav_twin:StaleFixtures', ...
            ['fixture version %d, this test expects %d. Regenerate the ' ...
             'fixtures, and read the diff -- a change in an expected ' ...
             'value is a change in what the twin is required to do.'], ...
            fx.version, EXPECTED_VERSION);
    end

    fprintf('ACAV twin cross-check against the Python reference\n');
    fprintf('%s\n', repmat('=', 1, 64));

    results = struct('name', {}, 'status', {}, 'detail', {});
    tol = 1e-9;

    results = quatAlgebra(results, fx, tol);
    results = attitudes(results, fx, tol);
    results = wheelCases(results, fx, tol);
    results = dynamicsCases(results, fx, tol);
    results = profileCases(results, fx, tol);
    results = controllerCases(results, fx, tol);
    results = modeCases(results, fx);
    results = wheelFaultCases(results, fx, tol);
    results = twinStepCases(results, fx, 1e-6);
    results = movingTwinStepCases(results, fx, 1e-6);
    results = closedLoopCases(results, fx);
    results = missionChart(results);

    fprintf('%s\n', repmat('-', 1, 64));
    failed = sum(strcmp({results.status}, 'FAIL'));
    fprintf('%d checks: %d passed, %d failed\n', numel(results), ...
        numel(results) - failed, failed);
    for k = 1:numel(results)
        if strcmp(results(k).status, 'FAIL')
            fprintf('  FAILED: %s\n', results(k).name);
        end
    end
    if failed == 0
        fprintf(['\nThe MATLAB twin reproduces the reference. Note this ' ...
                 'says nothing\nabout STK: run ' ...
                 'verify_acav_scenario.py for that.\n']);
    end

    if nargout > 0
        varargout{1} = results;
    elseif failed > 0
        error('test_acav_twin:Failed', ...
            '%d of %d checks failed; see the list above.', ...
            failed, numel(results));
    end
end

% -----------------------------------------------------------------------

function results = missionChart(results)
%MISSIONCHART Structural check of the Stateflow chart.
%
% The chart carries no fixtures -- it is graph structure, not numbers --
% but two of its properties are load-bearing enough to assert directly:
% SAFE must latch, and its guards must be evaluated before anything else
% leaving a state. Both are easy to break while editing the chart and
% neither shows up in a nominal run.
    if isempty(ver('stateflow'))
        results = record(results, 'chart: structure', true, ...
            'Stateflow not available; skipped');
        return
    end

    model = 'acav_chart_check';
    cleanup = onCleanup(@() closeQuietly(model));
    try
        if bdIsLoaded(model)
            close_system(model, 0);
        end
        new_system(model);
        chart = adcs.build_mission_chart(model, 'MissionMode', ...
            [100 100 400 300]);

        states = sort(string({chart.find('-isa', 'Stateflow.State').Name}));
        expected = sort(["NADIR" "SLEW" "SETTLE" "IMAGE" "SAFE"]);
        results = record(results, 'chart: states', ...
            isequal(states, expected), ...
            sprintf('got %s', strjoin(states, ', ')));

        transitions = chart.find('-isa', 'Stateflow.Transition');
        outgoing = 0; incoming = 0; priorities = [];
        for k = 1:numel(transitions)
            t = transitions(k);
            if ~isempty(t.Source) && strcmp(t.Source.Name, 'SAFE')
                outgoing = outgoing + 1;
            end
            if ~isempty(t.Destination) && strcmp(t.Destination.Name, 'SAFE')
                incoming = incoming + 1;
                priorities(end+1) = t.ExecutionOrder; %#ok<AGROW>
            end
        end

        results = record(results, 'chart: SAFE latches', outgoing == 0, ...
            sprintf(['SAFE has %d outgoing transitions; it must have ' ...
                     'none, or the vehicle oscillates in and out of ' ...
                     'SAFE and E5 replay stops being deterministic'], ...
                    outgoing));
        results = record(results, 'chart: SAFE reachable everywhere', ...
            incoming == 4, sprintf('%d of 4 nominal states can trip SAFE', ...
                                   incoming));
        results = record(results, 'chart: SAFE guards run first', ...
            ~isempty(priorities) && all(priorities == 1), ...
            sprintf(['execution orders %s; a wheel saturating during ' ...
                     'IMAGE must trip SAFE rather than be masked by an ' ...
                     'already-satisfied hold'], mat2str(priorities)));
    catch err
        results = record(results, 'chart: structure', false, err.message);
    end
end

function closeQuietly(model)
    if bdIsLoaded(model)
        close_system(model, 0);
    end
end

function cases = fixtureCases(value)
%FIXTURECASES Normalise a decoded JSON array to a cell array of structs.
%
% jsondecode returns a STRUCT ARRAY when every object in a JSON array
% has the same field names, and a CELL ARRAY when they differ. Fixture
% sections legitimately contain cases with different fields -- a
% rotation case has a `vector`, a scalar case has `expected_scalar` --
% so code written for one shape fails on the other with "Dot indexing
% is not supported for variables of this type", which says nothing
% whatever about the cause.
%
% Normalising here means adding a case with a new field can never break
% the harness again, which is worth more than making the JSON uniform:
% the JSON is meant to be readable, and padding every case with null
% fields it does not use would make it less so.
    if iscell(value)
        cases = value(:).';
    elseif isstruct(value)
        cases = num2cell(value(:).');
    else
        cases = {value};
    end
end

function results = record(results, name, ok, detail)
    entry = struct('name', name, 'status', 'pass', 'detail', detail);
    if ~ok
        entry.status = 'FAIL';
    end
    results(end+1) = entry; %#ok<AGROW>
    marker = "  ok  ";
    if ~ok
        marker = " FAIL ";
    end
    fprintf('[%s] %s\n', marker, name);
    if ~ok && strlength(detail) > 0
        fprintf('           %s\n', detail);
    end
end

function [ok, detail] = compareVec(actual, expected, tol)
    actual = actual(:).';
    expected = expected(:).';
    if numel(actual) ~= numel(expected)
        ok = false;
        detail = sprintf('length %d, expected %d', numel(actual), ...
            numel(expected));
        return
    end
    worst = max(abs(actual - expected));
    ok = worst <= tol;
    detail = sprintf('worst |diff| = %.3e (tol %.1e)\n           got      %s\n           expected %s', ...
        worst, tol, mat2str(actual, 12), mat2str(expected, 12));
end

function results = quatAlgebra(results, fx, tol)
    cases = fixtureCases(fx.quaternion_algebra);
    for k = 1:numel(cases)
        c = cases{k};
        switch c.name
            case 'multiply'
                got = adcs.quat.multiply(c.a.', c.b.');
                [ok, d] = compareVec(got, c.expected, tol);
            case 'rotate_inertial_x_into_body_after_90deg_yaw'
                got = adcs.quat.toBody(c.a.', c.vector.');
                [ok, d] = compareVec(got, c.expected(1:3), tol);
            case 'error_quaternion_is_body_referenced'
                got = adcs.quat.error(c.a.', c.b.');
                [ok, d] = compareVec(got, c.expected, tol);
            case 'boresight_error_ignores_roll'
                got = adcs.quat.boresightError(c.a.', c.b.', [0 0 1]);
                [ok, d] = compareVec(got, c.expected_scalar, tol);
            otherwise
                ok = false; d = 'unknown case';
        end
        results = record(results, ['quat: ' c.name], ok, d);
    end
end

function results = attitudes(results, fx, tol)
    boresight = fx.config.boresight_body.';
    cases = fixtureCases(fx.attitude_construction);
    for k = 1:numel(cases)
        c = cases{k};
        if strcmp(c.name, 'nadir')
            nadir = -c.position.' / norm(c.position);
            got = adcs.quat.align(boresight, nadir, [1 0 0], c.velocity.');
        else
            los = c.target.' - c.position.';
            got = adcs.quat.align(boresight, los / norm(los), ...
                [1 0 0], c.velocity.');
        end
        % Compare as attitudes, not as component tuples: q and -q are
        % the same attitude and Shepperd's branch selection may pick
        % either sign.
        angle = adcs.quat.pointingError(got, c.expected.');
        [ok, d] = compareVec(angle, 0, 1e-9);
        results = record(results, ['attitude: ' c.name], ok, d);
    end
end

function results = wheelCases(results, fx, tol)
    cfgFx = fx.config;
    cases = fixtureCases(fx.wheels);
    for k = 1:numel(cases)
        c = cases{k};
        [delivered, momentum, saturated] = adcs.wheels( ...
            c.torque_Nm.', c.dt, c.initial_momentum_Nms.', ...
            cfgFx.max_torque_Nm, cfgFx.momentum_capacity_Nms, ...
            c.health.');
        [okA, dA] = compareVec(delivered, c.expected_delivered_Nm, tol);
        [okB, dB] = compareVec(momentum, c.expected_momentum_Nms, tol);
        okC = saturated == c.expected_saturated;
        detail = dA;
        if ~okB
            detail = dB;
        elseif ~okC
            detail = sprintf('saturated flag %d, expected %d', ...
                saturated, c.expected_saturated);
        end
        results = record(results, ['wheels: ' c.name], ...
            okA && okB && okC, detail);
    end
end

function results = dynamicsCases(results, fx, tol)
    inertia = fx.config.inertia_kg_m2.';
    cases = fixtureCases(fx.dynamics);
    for k = 1:numel(cases)
        c = cases{k};
        q = [0 0 0 1];
        w = c.initial_rate_rad_s.';
        for step = 1:c.steps
            [q, w] = adcs.rigid_body_step(q, w, c.torque_Nm.', ...
                c.wheel_momentum_Nms.', inertia, c.dt);
        end
        angle = adcs.quat.pointingError(q, c.expected_quaternion.');
        [okA, dA] = compareVec(angle, 0, 1e-8);
        [okB, dB] = compareVec(w, c.expected_rate_rad_s, 1e-9);
        detail = dA;
        if ~okB
            detail = dB;
        end
        results = record(results, ['dynamics: ' c.name], okA && okB, detail);
    end
end

function results = profileCases(results, fx, tol)
    cfgFx = fx.config;
    inertia = cfgFx.inertia_kg_m2.';
    alpha = cfgFx.max_torque_Nm / inertia(1) * cfgFx.profile_authority;
    omegaMax = cfgFx.momentum_capacity_Nms / inertia(1) ...
        * cfgFx.profile_authority;

    cases = fixtureCases(fx.profile);
    for k = 1:numel(cases)
        c = cases{k};
        p = adcs.slew_profile(c.start.', c.finish.', alpha, omegaMax);
        [okD, dD] = compareVec(p.duration, c.expected_duration_s, 1e-9);
        [okA, dA] = compareVec(p.totalAngle, ...
            c.expected_total_angle_rad, 1e-9);

        ok = okD && okA;
        detail = dD;
        if ~okA
            detail = dA;
        end
        samples = fixtureCases(c.samples);
        for s = 1:numel(samples)
            sample = samples{s};
            [qRef, omegaRef] = p.referenceAt(sample.elapsed_s);
            angle = adcs.quat.pointingError(qRef, sample.quaternion.');
            [okQ, dQ] = compareVec(angle, 0, 1e-9);
            [okW, dW] = compareVec(omegaRef, sample.omega_rad_s, 1e-9);
            if ~okQ
                ok = false; detail = sprintf('t=%.3f q: %s', ...
                    sample.elapsed_s, dQ);
            elseif ~okW
                ok = false; detail = sprintf('t=%.3f w: %s', ...
                    sample.elapsed_s, dW);
            end
        end
        results = record(results, ['profile: ' c.name], ok, detail);
    end
end

function results = controllerCases(results, fx, tol)
    cfgFx = fx.config;
    inertia = cfgFx.inertia_kg_m2.';
    wn = cfgFx.natural_frequency_rad_s;
    kp = inertia * wn^2;
    kd = 2 * cfgFx.damping_ratio * wn * inertia;

    cases = fixtureCases(fx.controller);
    for k = 1:numel(cases)
        c = cases{k};
        got = adcs.tracking_torque(c.quaternion.', c.omega_rad_s.', ...
            c.quaternion_reference.', c.omega_reference_rad_s.', kp, kd);
        [ok, d] = compareVec(got, c.expected_torque_Nm, tol);
        results = record(results, ['controller: ' c.name], ok, d);
    end
end

function results = modeCases(results, fx)
    cfg = struct('settleEntryRad', fx.config.settle_entry_rad, ...
                 'maxBodyRateRadS', fx.config.max_body_rate_rad_s);
    cases = fixtureCases(fx.mode_chart);
    for k = 1:numel(cases)
        c = cases{k};
        got = adcs.mission_mode(c.mode_in, 0, 10, ...
            c.boresight_error_rad, c.body_rate_rad_s, ...
            c.momentum_fraction, logical(c.slew_requested), ...
            logical(c.profile_done), cfg);
        ok = strcmp(got, c.expected_mode);
        results = record(results, ['mode: ' c.name], ok, ...
            sprintf('got %s, expected %s', got, c.expected_mode));
    end
end

function results = wheelFaultCases(results, fx, tol)
%WHEELFAULTCASES E5's fault schedule, including the axis convention.
%
% ``axis`` is ZERO-based in the fixture because that is what the Python
% record writes; MATLAB indexes from one. Getting that wrong faults the
% wrong wheel while every other number in the run still looks right,
% which is why it is asserted rather than reviewed.
    cases = fixtureCases(fx.wheel_fault);
    for k = 1:numel(cases)
        c = cases{k};
        fault = struct('axis', c.fault.axis, 'atS', c.fault.at_s, ...
                       'health', c.fault.health, ...
                       'kind', char(c.fault.kind));
        [health, saturates] = adcs.wheel_fault(fault, c.time_s);

        [ok, detail] = compareVec(health, c.expected_health, tol);
        if ok && saturates ~= logical(c.expected_saturates)
            ok = false;
            detail = sprintf('saturates %d, expected %d', ...
                saturates, c.expected_saturates);
        end
        results = record(results, ['wheel fault: ' c.name], ok, detail);
    end
end

function cfg = twinCfgFromFixture(fx)
%TWINCFGFROMFIXTURE The cfg adcs.twin_step needs, from the fixture file.
%
% Built from the fixture rather than from adcs.config() on purpose: the
% expectations were generated against these values, and reading the YAML
% here would let a scenario edit silently change what the test compares
% against instead of failing loudly as a stale fixture.
    c = fx.config;
    inertia = c.inertia_kg_m2(:).';
    wn = c.natural_frequency_rad_s;

    cfg = struct();
    cfg.inertia = inertia;
    cfg.maxTorqueNm = c.max_torque_Nm;
    cfg.momentumCapacityNms = c.momentum_capacity_Nms;
    cfg.boresightBody = c.boresight_body(:).';
    cfg.settleEntryRad = c.settle_entry_rad;
    cfg.captureErrorRad = c.capture_error_rad;
    cfg.settleHoldS = c.settle_hold_s;
    cfg.maxBodyRateRadS = c.max_body_rate_rad_s;
    cfg.stepS = c.step_s;
    cfg.kp = inertia * wn^2;
    cfg.kd = 2 * c.damping_ratio * wn * inertia;
    cfg.profileAlphaRadS2 = c.max_torque_Nm / inertia(1) ...
        * c.profile_authority;
    cfg.profileOmegaMaxRadS = c.momentum_capacity_Nms / inertia(1) ...
        * c.profile_authority;
end

function results = twinStepCases(results, fx, tol)
%TWINSTEPCASES The per-step orchestration, replayed closed-loop.
%
% adcs.twin_step was the one function with no counterpart in the Python
% reference, so until these fixtures existed nothing cross-checked it --
% and two defects lived there through all of C3. The worse one was that
% quaternionCmd returned the input attitude verbatim: the twin computed
% a torque and published back the attitude it had just read, so the
% vehicle could never slew. This section exists so that cannot recur.
%
% Each step feeds the previous step's COMMANDED attitude back in as the
% next step's measurement, which is what the deployed loop does via STK.
% A twin that computes a torque without integrating it therefore shows
% up here as a boresight error that refuses to decrease.
%
% Checkpoint convention: quaternion/rate/wheel momentum are the state
% going INTO that step; mode/torque/boresight error are what the step
% produced from it.
%
% Tolerance is looser than the 1e-9 used for single-function cases, for
% the same reason closedLoopCases is: this accumulates a couple of
% hundred RK4 steps, and libm's last bit differs between platforms.
    baseCfg = twinCfgFromFixture(fx);
    cases = fixtureCases(fx.twin_step);

    for k = 1:numel(cases)
        c = cases{k};
        cfg = baseCfg;
        cfg.wheelFault = [];
        if isfield(c, 'fault') && ~isempty(c.fault) && isstruct(c.fault)
            cfg.wheelFault = struct( ...
                'axis', c.fault.axis, 'atS', c.fault.at_s, ...
                'health', c.fault.health, 'kind', char(c.fault.kind));
        end
        q = c.initial_quaternion(:).';
        w = c.initial_rate_rad_s(:).';
        state = adcs.initial_state();
        haveTarget = logical(c.have_target);
        position = c.position_m(:).';
        velocity = c.velocity_m_s(:).';
        targetEci = c.target_eci_m(:).';

        checkpoints = fixtureCases(c.checkpoints);
        next = 1;
        ok = true;
        detail = '';
        steps = round(c.duration_s / cfg.stepS);

        for index = 0:steps
            t = index * cfg.stepS;
            in = struct('quaternion', q, 'omega', w, ...
                        'position', position, 'velocity', velocity, ...
                        'targetEci', targetEci, 'haveTarget', haveTarget, ...
                        't', t);
            out = adcs.twin_step(in, cfg, state);

            if next <= numel(checkpoints) && ...
                    abs(t - checkpoints{next}.time_s) < cfg.stepS / 2
                [ok, detail] = compareTwinStep(checkpoints{next}, q, w, ...
                    state, out, tol);
                if ~ok
                    break
                end
                next = next + 1;
            end

            state = out.state;
            q = out.quaternionCmd;
            w = out.omegaNext;
        end

        if ok && next <= numel(checkpoints)
            ok = false;
            detail = sprintf('reached %d of %d checkpoints', ...
                next - 1, numel(checkpoints));
        end
        results = record(results, ['twin step: ' c.name], ok, detail);
    end
end

function results = movingTwinStepCases(results, fx, tol)
%MOVINGTWINSTEPCASES twin_step against MOVING geometry and target changes.
%
% The twin_step cases hold position, velocity and target fixed, so the
% paths that exist because the geometry moves were never cross-checked:
% the desired-rate feedforward, the slew profile transported with the
% line of sight, and the target-identity logic (re-plan on a change mid-
% SLEW, as a slew ends, or in SETTLE; reset on loss of target). Besides
% the checkpoints, every mode transition and every slew (re)plan time
% must match exactly, so a replan one side makes and the other does not
% is a named failure, not a drift several seconds later.
    cfg = twinCfgFromFixture(fx);
    cfg.wheelFault = [];
    geometry = fx.moving_geometry;
    cases = fixtureCases(fx.moving_twin_step);

    for k = 1:numel(cases)
        c = cases{k};
        schedule = fixtureCases(c.schedule);
        checkpoints = fixtureCases(c.checkpoints);
        expectedModes = fixtureCases(c.mode_transitions);
        expectedSlews = c.slew_starts_s(:).';

        q = c.initial_quaternion(:).';
        w = [0 0 0];
        state = adcs.initial_state();
        next = 1; ok = true; detail = '';
        modes = {}; modeTimes = []; slews = []; previousSlew = NaN;
        previousMode = '';
        steps = round(c.duration_s / cfg.stepS);

        for index = 0:steps
            t = index * cfg.stepS;
            targetId = '';
            for j = 1:numel(schedule)
                if t + 1e-9 >= schedule{j}.start_s
                    targetId = char(schedule{j}.target_id);
                end
            end
            [position, velocity, targetEci] = movingGeometry(geometry, t, targetId);
            in = struct('quaternion', q, 'omega', w, ...
                        'position', position, 'velocity', velocity, ...
                        'targetEci', targetEci, 'haveTarget', ~isempty(targetId), ...
                        't', t, 'targetId', targetId);
            out = adcs.twin_step(in, cfg, state);

            if ~strcmp(out.state.mode, previousMode)
                modes{end + 1} = out.state.mode; %#ok<AGROW>
                modeTimes(end + 1) = t; %#ok<AGROW>
                previousMode = out.state.mode;
            end
            if strcmp(out.state.mode, 'SLEW') && ...
                    ~isequal(out.state.slewStarted, previousSlew)
                slews(end + 1) = out.state.slewStarted; %#ok<AGROW>
            end
            previousSlew = out.state.slewStarted;

            if next <= numel(checkpoints) && ...
                    abs(t - checkpoints{next}.time_s) < cfg.stepS / 2
                [ok, detail] = compareTwinStep(checkpoints{next}, q, w, ...
                    state, out, tol);
                if ~ok
                    break
                end
                next = next + 1;
            end

            state = out.state;
            q = out.quaternionCmd;
            w = out.omegaNext;
        end

        if ok && next <= numel(checkpoints)
            ok = false;
            detail = sprintf('reached %d of %d checkpoints', next - 1, numel(checkpoints));
        end
        if ok
            expected = cellfun(@(e) char(e.mode), expectedModes, 'UniformOutput', false);
            expectedT = cellfun(@(e) e.time_s, expectedModes);
            if ~isequal(modes, expected) || any(abs(modeTimes - expectedT(:).') > cfg.stepS / 2)
                ok = false;
                detail = sprintf('mode transitions [%s] at [%s], expected [%s] at [%s]', ...
                    strjoin(modes, ' '), num2str(modeTimes), ...
                    strjoin(expected, ' '), num2str(expectedT(:).'));
            elseif numel(slews) ~= numel(expectedSlews) || ...
                    any(abs(slews - expectedSlews) > cfg.stepS / 2)
                ok = false;
                detail = sprintf('slew (re)plans at [%s], expected [%s]', ...
                    num2str(slews), num2str(expectedSlews));
            end
        end
        results = record(results, ['moving twin step: ' c.name], ok, detail);
    end
end

function [position, velocity, targetEci] = movingGeometry(g, t, targetId)
%MOVINGGEOMETRY Mirrors twin_fixtures.moving_geometry: a circular polar
% orbit, and a target fixed on a rotating Earth (zeros when none).
    angle = g.orbit_rate_rad_s * t;
    r = g.orbit_radius_m; w = g.orbit_rate_rad_s;
    position = [r * cos(angle), 0, r * sin(angle)];
    velocity = [-r * w * sin(angle), 0, r * w * cos(angle)];
    targetEci = [0 0 0];
    if ~isempty(targetId)
        target = g.targets.(targetId);
        longitude = target.lon_rad + g.earth_rate_rad_s * t;
        re = g.earth_radius_m;
        targetEci = [re * cos(target.lat_rad) * cos(longitude), ...
                     re * cos(target.lat_rad) * sin(longitude), ...
                     re * sin(target.lat_rad)];
    end
end

function [ok, detail] = compareTwinStep(cp, q, w, state, out, tol)
%COMPARETWINSTEP One checkpoint of a twin_step replay.
    ok = false;

    angle = adcs.quat.pointingError(q, cp.quaternion(:).');
    if angle > tol
        detail = sprintf('t=%.1f attitude differs by %.3e rad (%.5f deg)', ...
            cp.time_s, angle, rad2deg(angle));
        return
    end

    [rateOk, rateDetail] = compareVec(w, cp.rate_rad_s, tol);
    if ~rateOk
        detail = sprintf('t=%.1f body rate: %s', cp.time_s, rateDetail);
        return
    end

    [hOk, hDetail] = compareVec(state.wheelMomentum, ...
        cp.wheel_momentum_Nms, tol);
    if ~hOk
        detail = sprintf('t=%.1f wheel momentum: %s', cp.time_s, hDetail);
        return
    end

    [tauOk, tauDetail] = compareVec(out.torque, cp.torque_Nm, tol);
    if ~tauOk
        detail = sprintf('t=%.1f delivered torque: %s', cp.time_s, tauDetail);
        return
    end

    if out.wheelsSaturated ~= logical(cp.wheels_saturated)
        detail = sprintf('t=%.1f wheelsSaturated %d, expected %d', ...
            cp.time_s, out.wheelsSaturated, cp.wheels_saturated);
        return
    end

    if abs(out.state.wheelEnergyJ - cp.wheel_energy_J) > tol
        detail = sprintf(['t=%.1f wheel energy %.9e J, expected %.9e -- ' ...
            'a running integral, so a mismatch here means the two ' ...
            'implementations disagree about some EARLIER step'], ...
            cp.time_s, out.state.wheelEnergyJ, cp.wheel_energy_J);
        return
    end

    if abs(out.boresightErrorRad - cp.boresight_error_rad) > tol
        detail = sprintf(['t=%.1f boresight error %.9e, expected %.9e ' ...
            '-- if this grows rather than shrinks, the step is not ' ...
            'integrating the torque'], cp.time_s, ...
            out.boresightErrorRad, cp.boresight_error_rad);
        return
    end

    if ~strcmp(out.state.mode, cp.mode)
        detail = sprintf('t=%.1f mode %s, expected %s', cp.time_s, ...
            out.state.mode, cp.mode);
        return
    end

    ok = true;
    detail = '';
end

function results = closedLoopCases(results, fx)
    %CLOSEDLOOPCASES Whole-run agreement, coarsely.
    %
    % Step-by-step agreement over thousands of steps would fail on
    % floating-point summation order alone. What has to match is the
    % trajectory's shape and the numbers the study reports, so the
    % tolerance here is 1e-6 rad on attitude rather than 1e-9.
    cfgFx = fx.config;
    inertia = cfgFx.inertia_kg_m2.';
    wn = cfgFx.natural_frequency_rad_s;
    kp = inertia * wn^2;
    kd = 2 * cfgFx.damping_ratio * wn * inertia;
    alpha = cfgFx.max_torque_Nm / inertia(1) * cfgFx.profile_authority;
    omegaMax = cfgFx.momentum_capacity_Nms / inertia(1) ...
        * cfgFx.profile_authority;

    cases = fixtureCases(fx.closed_loop);
    for k = 1:numel(cases)
        c = cases{k};
        p = adcs.slew_profile(c.start.', c.target.', alpha, omegaMax);
        q = c.start.';
        w = [0 0 0];
        h = [0 0 0];
        steps = round(c.duration_s / c.dt);
        log = zeros(steps + 1, 9);   % t, q(4), err, h(3)
        for index = 0:steps
            t = index * c.dt;
            [qRef, omegaRef] = p.referenceAt(t);
            err = adcs.quat.boresightError(q, c.target.', ...
                cfgFx.boresight_body.');
            log(index + 1, :) = [t q err h];
            tau = adcs.tracking_torque(q, w, qRef, omegaRef, kp, kd);
            [delivered, h] = adcs.wheels(tau, c.dt, h, ...
                cfgFx.max_torque_Nm, cfgFx.momentum_capacity_Nms, [1 1 1]);
            [q, w] = adcs.rigid_body_step(q, w, delivered, h, inertia, c.dt);
        end

        ok = true;
        detail = '';
        checkpoints = fixtureCases(c.checkpoints);
        for s = 1:numel(checkpoints)
            cp = checkpoints{s};
            [~, row] = min(abs(log(:, 1) - cp.time_s));
            angle = adcs.quat.pointingError(log(row, 2:5), cp.quaternion.');
            if angle > 1e-6
                ok = false;
                detail = sprintf(['t=%.1f attitude differs by %.3e rad ' ...
                    '(%.4f deg)'], cp.time_s, angle, rad2deg(angle));
                break
            end
            if abs(log(row, 6) - cp.boresight_error_rad) > 1e-6
                ok = false;
                detail = sprintf(['t=%.1f boresight error %.6e, ' ...
                    'expected %.6e'], cp.time_s, log(row, 6), ...
                    cp.boresight_error_rad);
                break
            end
        end
        results = record(results, ['closed loop: ' c.name], ok, detail);
    end
end
